    ["mission|sandoria|0"] = {event = {15074280, 15074282, 15074300, 15075280, 15075282, 15075300, 15139816, 15139818, 15139836}, chat = {"bring me one of those axes, and your mission will be a success%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|1"] = {event = {12451844, 15074283, 15074303, 15075283, 15075303, 15139819, 15139839}, chat = {"deep in the tomb you'll find goblins%. take care; i don't want to lose you yet%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|10"] = {ki = {237}, event = {9764966, 9764969, 9764981, 15074292, 15074309, 15075292, 15075309, 15139828, 15139845, 15270441, 15270442}, zonein = {9764980}, chat = {"ah, it's you, .*i was waiting for you%.", "obtained key item: royal knights' davoi report", "prince trion has called for you%. head to his chamber inside chateau d'oraguille", "that's all three blocks covered%.", "the situation in davoi worsens by the day%.", "you've returned! zantaviat told me everything%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|11"] = {event = {15074293, 15074310, 15074311, 15075293, 15075310, 15075311, 15139829, 15139846, 15139847, 15270444}, zonein = {15270443}, chat = {"ah, that reminds me%-%-have you any fishing gear%?", "bandits infiltrating chateau d'oraguille is unprecedented in history!", "chalvatot, what has happened in my mother's chambers%?"}, lines = {["sandoria"] = true}},
    ["mission|sandoria|12"] = {ki = {30}, event = {12058624, 15270396, 15270425, 15925287, 15925290, 15925388}, chat = {"i've been waiting for you, .*you are to report to the embassy of san d'oria at jeuno%.", "obtained key item: letter to the ambassador", "welcome back%. her excellency has returned and is waiting for you%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|13"] = {ki = {14, 15, 16, 22, 56}, event = {15925284, 15925308, 15925376, 16056472}, chat = {"at long last you return! congratulations on your success!", "obtained key item: letter to aldo", "obtained key item: magicite: aurastone", "obtained key item: magicite: optistone", "obtained key item: magicite: orastone"}, lines = {["sandoria"] = true}},
    ["mission|sandoria|14"] = {ki = {72, 73}, event = {15270421, 15270422}, zonein = {13369345, 15270397}, chat = {"i'm not sure what it's about, but you'd best make haste%. the monarlais is not to be kept waiting!", "obtained key item: burnt seal", "obtained key item: new fei'yin seal", "we've come to a decision at last, .*we will send an expedition to the accursed northlands%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|15"] = {ki = {74}, event = {10813446, 15270434, 15270435, 15270436}, zonein = {10813447}, chat = {"i knew you were the one for the job%.", "obtained key item: shadow fragment", "prince trion was looking for you%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|16"] = {ki = {268}, event = {15269910, 15269912, 15269913, 15269975, 15269999}, chat = {"obtained key item: dreamrose", "the queen is sure to be pleased%.", "you are to retrieve", "you feel something prickly", "your mission has been issued by the late queen leaute herself%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|17"] = {ki = {269}, event = {12451845, 12451848, 15074313, 15074314, 15074315, 15074316, 15074317, 15074318, 15074319, 15074320, 15139849, 15139851, 15139853, 15139855, 15269909, 15269938, 15269969}, chat = {"i knew you would not let the kingdom down%.", "i will deliver this book to the scholars for deciphering%.", "obtained key item: ancient san d.orian book", "prince trion is calling for you%.", "will take a considerable amount of time%.", "you sense something evil%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|18"] = {ki = {283}, event = {15138823, 15138824}, chat = {"obtained key item: ancient san d.orian tablet", "something is amiss%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|19"] = {ki = {284}, event = {15074321, 15074322, 15074323, 15074324, 15139857, 15139859, 15269888}, chat = {"obtained key item: crystal dowser", "the fair claidie i d.oraguille has invited you to the chateau%.", "well, congratulations on the completion of your mission%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|2"] = {ki = {157}, event = {9175043, 9175095, 15074284, 15074304, 15075284, 15075304, 15139509, 15139820, 15139840}, chat = {"but, i wonder what that orc meant%.%.%.", "obtained key item: orcish hut key", "orcs tend to keep their hostages in tents or small huts%. once you're inside the compound, check them first%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|20"] = {ki = {288}, event = {15269946, 15269990}, zonein = {15138832, 15270004}, chat = {"obtained key item: drops of amnio", "requires much preparation%. this is where your assistance is necessary", "tradition prohibits us from allowing you to attend the ceremony", "you sense something evil%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|21"] = {ki = {285, 286, 287}, event = {10420289, 15269988, 15269992, 15269994, 15269995}, chat = {"begin to quiver!", "i want you to investigate the temple of uggalepih%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|22"] = {ki = {481, 482, 483}, event = {6882184, 7340044, 8388608, 15269920, 15269964}, chat = {"obtained key item: figure of garuda", "obtained key item: figure of leviathan", "obtained key item: figure of titan", "you sense something lurking close by!"}, lines = {["sandoria"] = true}},
