    ["mission|sandoria|3"] = {ki = {65}, event = {6684782, 6684784, 6684785, 6684786, 6684787, 12648449, 12648450, 15074285, 15075285, 15139821}, chat = {"an adventurer, are you%? i am ruillont of the temple knights%.", "are you in the rescue drill%?", "it's all just a drill, so this should be easy compared to your usual fare%.", "my sword! you've brought me my sword!", "obtained key item: rescue training certificate", "ruillont's sword%? yes, i was keeping it for him during training%.", "what%? ruillont's in that cave%? and he doesn't want us to send help, eh%?", "you've returned! i hear the drill turned into something far more perilous%."}, lines = {["sandoria"] = true}},
    ["mission|sandoria|4"] = {ki = {44, 103}, event = {9764964, 9764968, 15074286, 15074308, 15075286, 15075308, 15139511, 15139822, 15139844}, chat = {"a message%? finally! i am zantaviat of the temple knights%.", "obtained key item: lost document", "obtained key item: temple knights' davoi report", "the scout's name is zantaviat%. he's somewhere in davoi, but where i cannot say%.", "you found the page! well done%.", "you were told to hand the .* to prince pieuje personally%?"}, lines = {["sandoria"] = true}},
    ["mission|sandoria|5"] = {ki = {13, 32, 34}, event = {9502762, 15270393, 15270395, 15532236, 15532238, 15532387, 15532455, 15532457, 15532458, 15794624, 15794633, 15794638, 15794643, 15859950, 15859954}, chat = {"ah, you are .*, are you not%? i've heard word of you from the gatehouse%.", "good%. good%. hoot!", "here, take these .*good luck%. you're gonna need it%.", "let's see the report you've brought back, then!", "never mind, shouting at you won't change anything%.", "obtained key item: dark key", "obtained key item: kindred crest", "obtained key item: shield offering"}, lines = {["sandoria"] = true}},
