    ["mission|windurst|0"] = {ki = {28}, event = {7602229, 12582954, 12582960, 12582962, 12582964, 12582966, 12582968, 12582970, 15597686, 15663200, 15728723, 15728730, 15728731, 15728734, 15794297}, chat = {"obtained key item: cracked mana orb", "the ministerrr of the orastery is in the laborrratory beneath here%."}, lines = {["windurst"] = true}},
    ["mission|windurst|1"] = {ki = {37, 59, 112}, event = {7602222, 12714028, 12714030, 12714031, 12714032, 12714033, 12714034, 12714035, 12714042, 12714043, 12714044, 12714045, 12714046, 12714047, 15597699, 15663211, 15728745, 15794312, 15794313, 15794314, 15794319, 15794321}, chat = {"ask pore%-ohre in the southeastern magic tower of the horutoto ruins to find out how to energize mana orbs properly%.", "go ask the staff at the cardian workshop in the manustery for the details of your mission%.", "i'm sure the minister of the manustery will fill you in on the details of your mission%.", "thank you very muchy%-wuchy!", "the manustery's cardian workshop is southeast of here, in windurst woods%."}, lines = {["windurst"] = true}},
    ["mission|windurst|10"] = {ki = {36}, event = {9895979, 15728787, 15728788, 15859815, 15859816, 15859819, 15859820, 15859825, 15859826}, chat = {"have i seen the orastery minister%? he just stormed out of here a few minutes ago%.", "or more to the point, why would our ding%-a%-ling minister head off to such a dangerous place as castle oztroja on his own%?", "orastery minister, ajido%-marujido%.%.%.", "when visiting the upper floors of the tower, you must be on your"}, lines = {["windurst"] = true}},
    ["mission|windurst|11"] = {ki = {66}, event = {12582953, 15794364, 15859832, 15859833, 15859834, 15859847, 15859862, 15859863, 15859969}, chat = {"i am impressed that a mere adventurer such as yourself was able to carry out my biddy%-bidding%.", "i would like you to travel to the central tower of the horutoto ruins", "journey to the central tower of the horutoto ruins and rid the place of those pernicious%-vicious vermin%.", "the head lady%-in%-waiting, zubaba, is expecting you at heavens tower%.", "you say that the old%.%.%.the head lady%-in%-waiting, zubaba, requests your audience%?"}, lines = {["windurst"] = true}},
    ["mission|windurst|12"] = {ki = {30}, event = {12058626, 15859865, 15859874, 15925288, 15925291, 15925316, 15925389}, chat = {"how go your adventures%? are you finally starting to make a name for yourself in windurst%?", "welcome back! the ambassador has returned, and wants to see you%."}, lines = {["windurst"] = true}},
